import React, { useMemo } from "react";
import { IconCommon, IconDesktop, IconPublic, IconRight } from "@arco-design/web-react/icon";
import { Button, Message } from "@arco-design/web-react";
import styles from './index.module.less';
import app from "@/store/app";

interface DevCardProps {
    type: "manage" | "pc"
}
export const DevCard = ({ type }: DevCardProps) => {

    const iconRender = useMemo(() => {
        switch(type){
            case "manage":
                return <IconCommon />;
            break;
            case "pc":
                return <IconDesktop />
        }
    },[type])

    const item = useMemo(() => {
        switch(type){
            case "manage":
                return {
                    bgColor: "#17171a",
                    url: "http://wizui-assets.oss-cn-hangzhou.aliyuncs.com/assets/system/24/02/c6/ad/27accf39d0cf6abc.png",
                    name: "管理后台",
                    description: "搭建管理页面，权限、路由配置管理。",
                    onClick: () => {
                        Message.info("正在搭建中，暂未开放")
                    },
                    buttonText: "去设计"
                }
            case "pc":
                return {
                    bgColor: "#678ff4",
                    url: "http://wizui-assets.oss-cn-hangzhou.aliyuncs.com/assets/system/24/01/2f/f8/ae2a3ba50b254a5f.png",
                    name: "电脑网站",
                    description: "拖拽排版，10分钟完成搭建，专注网站开发。",
                    onClick: () => {
                        window.open(`#/dev/${app.info.mark}/`)
                    },
                    buttonText: "去设计"
                }
        }
    }, [type])

    return (
        <div className={styles.card}
            style={{
                background: item.bgColor
            }}
        >
            <img className={styles.img} src={item.url} />
            <div className={styles.title}>
                {iconRender} {item.name}
            </div>
            <div className={styles.description}>
                
            </div>
            <div className={styles.button}
                onClick={item.onClick}
                style={{
                    color: item.bgColor
                }}
            >
                {item.buttonText}<IconRight />
            </div>
        </div>
    )
}

export default DevCard;